# SM3 09B - Verify reference video analyzer readiness/state\n[CmdletBinding()]\nparam([string]$WorkerBaseUrl='http://localhost:8090')\nSet-StrictMode -Version Latest\n$ErrorActionPreference='Stop'\n$base=$WorkerBaseUrl.TrimEnd('/')\n$h=Invoke-RestMethod "$base/health" -TimeoutSec 20\n$s=Invoke-RestMethod "$base/production/reference-corpus/summary" -TimeoutSec 30\nif($h.version -ne '2.16.0' -or\n   $h.reference_video_analysis -ne $true -or\n   $h.reference_video_analysis_contract -ne 'SM3_REFERENCE_VIDEO_ANALYSIS_V1' -or\n   $h.reference_video_analyzer_version -ne 'SM3_REFERENCE_VIDEO_ANALYZER_V1' -or\n   $h.reference_video_vision_schema -ne 'SM3_REFERENCE_VIDEO_VISION_V1' -or\n   $h.reference_feature_contract -ne 'SM3_REFERENCE_FEATURES_V1' -or\n   $h.reference_feature_idempotency_stable -ne $true -or\n   $h.reference_foundation_override_allowed -ne $false -or\n   $h.reference_copying_allowed -ne $false -or\n   $h.ffmpeg -ne $true -or $h.ffprobe -ne $true){ throw 'SM3_09B_REFERENCE_VIDEO_ANALYZER_HEALTH_INVALID' }\nWrite-Output 'SM3_09B_REFERENCE_VIDEO_ANALYZER_VERIFY_PASS'\n[pscustomobject]@{\n worker_version=$h.version\n profile_count=$s.profile_count\n item_count=$s.item_count\n feature_observation_count=$s.feature_observation_count\n analysis_contract=$h.reference_video_analysis_contract\n analyzer_version=$h.reference_video_analyzer_version\n vision_schema=$h.reference_video_vision_schema\n vision_model=$h.vision_model\n vision_configured=$h.vision_configured\n scene_metrics=$h.reference_video_mechanical_scene_metrics\n audio_onset_sync=$h.reference_video_audio_onset_sync_evidence\n adaptive_color_metrics=$h.reference_video_adaptive_color_metrics\n feature_idempotency_stable=$h.reference_feature_idempotency_stable\n}\n